import React, { useState } from 'react';

interface LoginFormProps {
  onSubmit: (email: string, password: string) => void;
}

const LoginForm: React.FC<LoginFormProps> = ({ onSubmit }) => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [errors, setErrors] = useState<{ email?: string; password?: string; }>({
    email: undefined,
    password: undefined,
  });
  const [submitting, setSubmitting] = useState(false);

  const validateEmail = (value: string) => {
    const emailRegex = /^[\w-\.]+@([\w-]+\.)+[\w-]{2,4}$/;
    return emailRegex.test(value) ? undefined : 'Invalid email format';
  };

  const validatePassword = (value: string) => {
    return value.length >= 8 ? undefined : 'Password must be at least 8 characters long';
  };

  const handleSubmit = (event: React.FormEvent) => {
    event.preventDefault();

    if (submitting) {
      return;
    }

    setSubmitting(true);

    const emailError = validateEmail(email);
    const passwordError = validatePassword(password);

    if (emailError || passwordError) {
      setErrors({ email: emailError, password: passwordError });
      setSubmitting(false);
      return;
    }

    onSubmit(email, password);
    setSubmitting(false);
  };

  return (
    <form onSubmit={handleSubmit}>
      <div>
        <label htmlFor="email">Email:</label>
        <input
          type="email"
          id="email"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
        />
        {errors.email && <p className="error">{errors.email}</p>}
      </div>
      <div>
        <label htmlFor="password">Password:</label>
        <input
          type="password"
          id="password"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
        />
        {errors.password && <p className="error">{errors.password}</p>}
      </div>
      <button type="submit" disabled={submitting}>
        {submitting ? 'Submitting...' : 'Login'}
      </button>
    </form>
  );
};

export default LoginForm;

import { useState, useEffect, useRef, useCallback } from 'react';

interface UseFetchResult<T> {
  data: T | undefined;
  loading: boolean;
  error: Error | undefined;
}

/**
 * Custom React hook for fetching data from a URL.
 */
export function useFetch<T>(url: string | null): UseFetchResult<T> {
  const [data, setData] = useState<T | undefined>(undefined);
  const [loading, setLoading] = useState<boolean>(false);
  const [error, setError] = useState<Error | undefined>(undefined);
  const abortControllerRef = useRef<AbortController | null>(null);

  const fetchData = useCallback(async () => {
    if (!url) {
      return;
    }

    abortControllerRef.current = new AbortController();

    try {
      setLoading(true);
      const response = await fetch(url, {
        signal: abortControllerRef.current?.signal,
      });

      if (!response.ok) {
        throw new Error(`HTTP error! Status: ${response.status}`);
      }

      const jsonData: T = await response.json();
      setData(jsonData);
      setError(undefined);
    } catch (e: any) {
      if (e.name === 'AbortError') {
        // Request was aborted, do nothing
        console.log('Fetch aborted');
      } else {
        setError(e as Error);
        setData(undefined);
      }
    } finally {
      setLoading(false);
    }
  }, [url]);

  useEffect(() => {
    if (url) {
      fetchData();
    }

    return () => {
      abortControllerRef.current?.abort();
    };
  }, [url, fetchData]);

  return { data, loading, error };
}

import React, { useReducer } from 'react';

interface Todo {
  id: number;
  text: string;
  completed: boolean;
}

interface State {
  todos: Todo[];
  filter: 'all' | 'active' | 'completed';
}

const todoReducer = (state: State, action: {
  type: string;
  payload?: any;
}) => {
  switch (action.type) {
    case 'ADD':
      return {
        ...state,
        todos: [...state.todos, { id: Date.now(), text: action.payload, completed: false }],
      };
    case 'TOGGLE':
      return {
        ...state,
        todos: state.todos.map((todo) =>
          todo.id === action.payload ? { ...todo, completed: !todo.completed } : todo
        ),
      };
    case 'DELETE':
      return {
        ...state,
        todos: state.todos.filter((todo) => todo.id !== action.payload),
      };
    case 'SET_FILTER':
      return {
        ...state,
        filter: action.payload,
      };
    default:
      return state;
  }
};

const TodoApp = () => {
  const initialState: State = {
    todos: [],
    filter: 'all',
  };

  const [state, dispatch] = useReducer(todoReducer, initialState);

  const handleAddTodo = (text: string) => {
    dispatch({ type: 'ADD', payload: text });
  };

  const handleToggleTodo = (id: number) => {
    dispatch({ type: 'TOGGLE', payload: id });
  };

  const handleDeleteTodo = (id: number) => {
    dispatch({ type: 'DELETE', payload: id });
  };

  const handleSetFilter = (filter: 'all' | 'active' | 'completed') => {
    dispatch({ type: 'SET_FILTER', payload: filter });
  };

  const visibleTodos = (
    state.filter === 'active'
      ? state.todos.filter((todo) => !todo.completed)
      : state.filter === 'completed'
        ? state.todos.filter((todo) => todo.completed)
        : state.todos
  );

  return (
    <div>
      <h1>Todo App</h1>
      <div>
        <input
          type="text"
          placeholder="Add todo"
          onKeyDown={(e) => {
            if (e.key === 'Enter') {
              handleAddTodo(e.target.value);
            }
          }}
        />
      </div>
      <ul>
        {visibleTodos.map((todo) => (
          <li key={todo.id}>
            <input
              type="checkbox"
              checked={todo.completed}
              onChange={() => handleToggleTodo(todo.id)}
            />
            <span style={{ textDecoration: todo.completed ? 'line-through' : 'none' }}>
              {todo.text}
            </span>
            <button onClick={() => handleDeleteTodo(todo.id)}>Delete</button>
          </li>
        ))}
      </ul>
      <div>
        <button onClick={() => handleSetFilter('all')}>All</button>
        <button onClick={() => handleSetFilter('active')}>Active</button>
        <button onClick={() => handleSetFilter('completed')}>Completed</button>
      </div>
    </div>
  );
};

export default TodoApp;

import { Request, Response, NextFunction } from 'express';

// In-memory storage for API keys (replace with a database in production)
const apiKeys = new Set<string>(
  [
    'valid-api-key-123',
    'another-valid-key',
  ]
);

/**
 * Middleware to validate an API key from the Authorization header.
 */
export const authMiddleware = (req: Request, res: Response, next: NextFunction):
  void => {
  const Authorization = req.headers.authorization;

  if (!Authorization) {
    return res.status(401).json({
      error: 'Authorization header missing',
    });
  }

  if (!Authorization.startsWith('Bearer ')) {
    return res.status(401).json({
      error: 'Invalid authorization format.  Expected "Bearer [API Key]"',
    });
  }

  const apiKey = Authorization.substring(7);

  if (!apiKeys.has(apiKey)) {
    return res.status(401).json({
      error: 'Invalid API key',
    });
  }

  // API key is valid, proceed to the next middleware or route handler
  next();
};

import { setTimeout, clearTimeout } from 'timers/promises';

/**
 * Creates a debounced function that delays invoking a function until after
 * `wait` milliseconds have elapsed since the last time the debounced function
 * was invoked.  The `leading` option allows the function to be invoked
 * immediately on the leading edge of the timeout, rather than waiting for the
 * timeout to complete. The `trailing` option allows the function to be invoked
 * on the trailing edge of the timeout.
 *
 * @template T An array of any type.
 *
 * @param {Function} func The function to debounce.
 * @param {number} wait The number of milliseconds to wait before invoking `func`.
 * @param {object} options An object containing the `leading` and `trailing` options.
 * @returns {Function & { cancel: () => void }} A debounced version of `func`.
 */
export function debounce<T extends unknown[]>(func: (...args: T) => any, wait: number, options: { leading?: boolean; trailing?: boolean } = {}): Function & { cancel: () => void } { 
  let timeout: NodeJS.Timeout | null = null;
  let lastArgs: T | null = null;
  let lastThis: any = null;

  const debounced = function(...args: T) {
    lastArgs = args;
    lastThis = this;

    if (!timeout) {
      if (options.leading) {
        func.apply(this, args);
      }
    }

    timeout = setTimeout(() => {
      timeout = null;
      if (options.trailing && lastArgs) {
        func.apply(lastThis, lastArgs);
      }
    }, wait);
  } as Function & { cancel: () => void };

  debounced.cancel = () => {
    if (timeout) {
      clearTimeout(timeout);
      timeout = null;
    }
  };

  return debounced;
}
